const route = (value: string, previous = false): string => {
  const text = value.toLowerCase();
  if (text === 'pendiente' || text.includes('pendiente') || text.includes('por confirmar') || text.includes('por verificar')) return value;
  if (text.includes('primera actividad del destino')) return 'Sin tramo previo definido; trayecto de llegada al destino.';
  if (text === 'alojamiento' || text === 'hotel base' || text === 'hotel mi rochor' || text === 'star residence' || text.includes('pausa en alojamiento')) return 'Sin traslado; actividad en el alojamiento.';
  if (text.includes('≈') || /\d+\s*min/.test(text)) return `${value} Confirmar el tiempo y la ruta en el mapa el día del traslado.`;
  if (text.includes('alojamiento') || text.includes('hotel base')) return 'Sin traslado; actividad en el alojamiento.';
  const estimate = text.includes('changi') || text.includes('aeropuerto') || text.includes('kul →')
    ? '≈45–90 min de traslado, estimación sin tráfico ni espera'
    : text.includes('batu caves')
      ? '≈35–60 min en Grab, estimación sujeta al tráfico'
      : text.includes('grab')
        ? '≈20–60 min en Grab, estimación sujeta al tráfico'
        : text.includes('mrt') || text.includes('lrt')
          ? '≈15–40 min en transporte público, estimación sin espera ni transbordos'
        : text.includes('a pie') || text.includes('paseo')
            ? '≈5–25 min a pie, estimación sujeta a la entrada y recorrido real'
            : '≈10–30 min, estimación de tramo local por verificar';
  return `${value} · ${previous ? 'tramo previo' : 'desde el hotel'} ${estimate}. Confirmar en el mapa el día de la visita.`;
};

const a = (date: string, id: string, title: string, time: string, duration: number, placeId: string, zone: string, effort: Activity['effort'], priority: Activity['priority'], food: string, tickets: string, rain: string, detail: string, fromHotel: string, fromPrevious: string, flight?: Activity['flight'], localTime?: string): Activity => ({ id, date, title, time, duration, placeId, zone, effort, priority, food, tickets, rain, detail, fromHotel: route(fromHotel), fromPrevious: route(fromPrevious, true), status: 'pending', ...(flight ? { flight } : {}), ...(localTime ? { localTime } : {}) });

